  id String @id

  /// Identifier of the product category this inventory summary record belongs
  /// to. {@link shopping_mall_categories.id}.
  category_id String

  /// Total number of distinct SKUs under the product category.
  total_sku_count Int

  /// Aggregate quantity of all SKU items available in stock within the
  /// category.
  total_inventory_quantity Int

  /// SKU inventory level considered low stock threshold for alerting.
  low_stock_threshold Int

  /// Number of SKUs currently below the low stock threshold within this
  /// category.
  low_stock_sku_count Int

  /// Timestamp when this materialized view was last refreshed.
  last_refreshed_at DateTime

  //----
  // RELATIONS
  //----
  @@index([category_id])
}

