import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallMileage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallMileage";

export async function test_api_customer_mileage_creation_by_authenticated_customer(
  connection: api.IConnection,
) {
  // 1. Register a new customer via join authentication.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "http://localhost/login",
    referrer: "http://localhost/",
  } satisfies IShoppingMallCustomer.ICreate;

  const authorized: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, { body: joinBody });
  typia.assert(authorized);

  // 2. Create a new mileage record with valid points and optional expiration.
  const createBody: IShoppingMallMileage.ICreate = {
    points: RandomGenerator.pick([1, 5, 10, 20, 50, 100]) satisfies number,
    expiration_date:
      Math.random() > 0.5
        ? new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString()
        : null,
  } satisfies IShoppingMallMileage.ICreate;

  const mileage: IShoppingMallMileage =
    await api.functional.shoppingMall.customer.mileages.create(connection, {
      body: createBody,
    });
  typia.assert(mileage);

  // 3. Validate customer association and points correctness
  TestValidator.equals(
    "mileage.shopping_mall_customer_id matches authorized.customer.id",
    mileage.shopping_mall_customer_id,
    authorized.id,
  );
  TestValidator.predicate(
    "mileage.points is positive integer",
    Number.isInteger(mileage.points) && mileage.points > 0,
  );
  // expiration_date can be null or string in ISO format, typia.assert() validates format
  TestValidator.predicate(
    "mileage.expiration_date is null or valid ISO date string",
    mileage.expiration_date === null ||
      typeof mileage.expiration_date === "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallMileage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallMileage";

export async function test_api_customer_mileage_retrieval_by_owner(
  connection: api.IConnection,
) {
  // 1. Authenticate as a new customer to establish authorization
  const email = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: email,
        password: "password123",
        href: "https://example.com/signup",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 2. Create a mileage record for the authenticated customer
  const createBody = {
    points: RandomGenerator.pick([10, 20, 50, 100, 200] as const),
    expiration_date: null,
  } satisfies IShoppingMallMileage.ICreate;
  const mileage: IShoppingMallMileage =
    await api.functional.shoppingMall.customer.mileages.create(connection, {
      body: createBody,
    });
  typia.assert(mileage);
  TestValidator.equals(
    "mileage shopping_mall_customer_id matches customer id",
    mileage.shopping_mall_customer_id,
    customer.id,
  );

  // 3. Retrieve the mileage record by mileageId as the same customer
  const retrieved: IShoppingMallMileage =
    await api.functional.shoppingMall.customer.mileages.at(connection, {
      mileageId: mileage.id,
    });
  typia.assert(retrieved);
  // Validate the retrieved data matches created one
  TestValidator.equals(
    "retrieved mileage id matches created id",
    retrieved.id,
    mileage.id,
  );
  TestValidator.equals(
    "retrieved points match",
    retrieved.points,
    createBody.points,
  );
  TestValidator.equals(
    "retrieved shopping_mall_customer_id matches",
    retrieved.shopping_mall_customer_id,
    customer.id,
  );
  TestValidator.equals(
    "retrieved expiration_date is null",
    retrieved.expiration_date,
    null,
  );

  // 4. Authenticate as a different new customer
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherCustomer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: otherEmail,
        password: "password123",
        href: "https://example.com/signup",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(otherCustomer);

  // 5. Attempt to retrieve the mileage record created by the first customer while authenticated as the other customer
  // Expect an error due to access control
  await TestValidator.error(
    "should fail retrieval by different customer",
    async () => {
      await api.functional.shoppingMall.customer.mileages.at(connection, {
        mileageId: mileage.id,
      });
    },
  );

  // Note: No additional tokens or headers are set manually; SDK handles auth context internally.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";

export async function test_api_shopping_mall_order_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin account creation
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password1234",
    ip: null,
    href: "http://localhost",
    referrer: "http://localhost",
  } satisfies IShoppingMallAdmin.IJoin;
  const adminAccount = await api.functional.auth.admin.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(adminAccount);

  // 2. Admin login
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "http://localhost",
    referrer: "http://localhost",
  } satisfies IShoppingMallAdmin.ILogin;
  await api.functional.auth.admin.login(connection, { body: adminLoginBody });

  // 3. Customer account creation
  const customerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password1234",
    href: "http://localhost",
    referrer: "http://localhost",
  } satisfies IShoppingMallCustomer.ICreate;
  const customerAccount = await api.functional.auth.customer.join(connection, {
    body: customerJoinBody,
  });
  typia.assert(customerAccount);

  // 4. Customer login
  const customerLoginBody = {
    email: customerJoinBody.email,
    password: customerJoinBody.password,
    ip: null,
    href: "http://localhost",
    referrer: "http://localhost",
  } satisfies IShoppingMallCustomer.ILogin;
  await api.functional.auth.customer.login(connection, {
    body: customerLoginBody,
  });

  // 5. Create an order by customer
  // Use order_number, order_status, payment_status, total_amount, shipping_address according to schema
  const newOrderBody = {
    order_number: `ORD-${Date.now()}`,
    order_status: "pending",
    payment_status: "unpaid",
    total_amount: 10000,
    shipping_address: "123 Test Street, Test City, Test Country",
  } satisfies IShoppingMallOrder.ICreate;
  const createdOrder = await api.functional.shoppingMall.customer.orders.create(
    connection,
    { body: newOrderBody },
  );
  typia.assert(createdOrder);

  // 6. Switch back to Admin login to perform deletion
