import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";

export async function test_api_customer_create_shipment(
  connection: api.IConnection,
) {
  // 1. Register new customer user
  const customerCreationBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(8),
    href: RandomGenerator.alphaNumeric(20),
    referrer: RandomGenerator.alphaNumeric(20),
  } satisfies IShoppingMallCustomer.ICreate;
  const authorizedCustomer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerCreationBody,
    });
  typia.assert(authorizedCustomer);

  // 2. Create a new order associated with the customer
  // Compose order create data with required properties
  const orderCreateBody = {
    order_number: `ORDER-${RandomGenerator.alphaNumeric(10)}`,
    order_status: "pending",
    payment_status: "pending",
    total_amount: RandomGenerator.alphabets(5).length * 10, // some arbitrary positive amount
    shipping_address: RandomGenerator.alphaNumeric(30),
  } satisfies IShoppingMallOrder.ICreate;
  const createdOrder: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderCreateBody,
    });
  typia.assert(createdOrder);

  // 3. Create shipment linked to the created order
  const shipmentCreateBody = {
    shopping_mall_order_id: createdOrder.id,
    shipping_carrier: "FedEx",
    tracking_number: `TRACK${RandomGenerator.alphaNumeric(8)}`,
    shipment_status: "pending",
    shipped_at: null,
    delivered_at: null,
  } satisfies IShoppingMallShipment.ICreate;
  const createdShipment: IShoppingMallShipment =
    await api.functional.shoppingMall.customer.shipments.create(connection, {
      body: shipmentCreateBody,
    });
  typia.assert(createdShipment);

  // Validate the shipment is correctly linked to the order
  TestValidator.equals(
    "shipment order ID should match order ID",
    createdShipment.shopping_mall_order_id,
    createdOrder.id,
  );
  TestValidator.equals(
    "shipment status should be 'pending'",
    createdShipment.status,
    "pending",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";

export async function test_api_seller_update_shipment(
  connection: api.IConnection,
) {
  // 1. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "P@ssw0rd!", // realistic password value
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 2. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "P@ssw0rd!",
        href: "https://example.com/signup",
        referrer: "https://google.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 3. Customer creates an order
  const orderNumber = RandomGenerator.alphaNumeric(10);
  const orderStatus = "pending";
  const paymentStatus = "pending";
  const shippingAddress = "123 Example Road, Example City, EX 12345";
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: {
        order_number: orderNumber,
        order_status: orderStatus,
        payment_status: paymentStatus,
        total_amount: 10000, // realistic total amount
        shipping_address: shippingAddress,
      } satisfies IShoppingMallOrder.ICreate,
    });
  typia.assert(order);

  // 4. Customer creates a shipment linked to the order
  const shipmentStatus = "pending";
  const shipmentCarrier = "DHL";
  const trackingNumber = RandomGenerator.alphaNumeric(12).toUpperCase();
  const shipmentCreateBody = {
    shopping_mall_order_id: order.id,
    shipping_carrier: shipmentCarrier,
    tracking_number: trackingNumber,
    shipment_status: shipmentStatus,
    shipped_at: null,
    delivered_at: null,
  } satisfies IShoppingMallShipment.ICreate;
  const shipment: IShoppingMallShipment =
    await api.functional.shoppingMall.customer.shipments.create(connection, {
      body: shipmentCreateBody,
    });
  typia.assert(shipment);

  // 5. Seller login to set correct auth context
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "P@ssw0rd!",
      ip: null,
      href: "https://example.com/login",
      referrer: "https://google.com",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 6. Seller updates shipment details
  const updatedCarrier = "FedEx";
  const updatedTrackingNumber = RandomGenerator.alphaNumeric(14).toUpperCase();
  const updatedStatus = "shipped";
  const updatedShippedAt = new Date().toISOString();

  const shipmentUpdateBody = {
    shipping_carrier: updatedCarrier,
    tracking_number: updatedTrackingNumber,
    status: updatedStatus,
    shipped_at: updatedShippedAt,
    delivered_at: null,
  } satisfies IShoppingMallShipment.IUpdate;

  const updatedShipment: IShoppingMallShipment =
    await api.functional.shoppingMall.seller.shipments.update(connection, {
      shipmentId: shipment.id,
      body: shipmentUpdateBody,
    });
  typia.assert(updatedShipment);

  // Validations
  TestValidator.equals("shipment id matches", updatedShipment.id, shipment.id);
  TestValidator.equals(
    "shipment order id matches",
    updatedShipment.shopping_mall_order_id,
    order.id,
  );
  TestValidator.equals(
    "shipment carrier updated",
    updatedShipment.shipping_carrier,
    updatedCarrier,
  );
  TestValidator.equals(
    "shipment tracking number updated",
    updatedShipment.tracking_number,
    updatedTrackingNumber,
  );
  TestValidator.equals(
    "shipment status updated",
    updatedShipment.status,
    updatedStatus,
  );
  TestValidator.equals(
    "shipment shipped_at updated",
    updatedShipment.shipped_at,
    updatedShippedAt,
  );
  TestValidator.equals(
    "shipment delivered_at is null",
    updatedShipment.delivered_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

export async function test_api_admin_token_refresh_with_valid_refresh_token(
  connection: api.IConnection,
) {
  // 1. Register a new admin user to obtain initial authorization tokens
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password = "password123";
  const href: string & tags.Format<"uri"> = "https://example.com/register";
  const referrer: string & tags.Format<"uri"> = "https://example.com";

  const joinBody = {
    email: email,
    password: password,
    ip: null,
    href: href,
    referrer: referrer,
  } satisfies IShoppingMallAdmin.IJoin;

  const authorized: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Use the refresh token from initial authentication to request new tokens
  const refreshBody = {
    refreshToken: authorized.token.refresh,
  } satisfies IShoppingMallAdmin.IRefresh;

  const refreshed: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshed);

  // 3. Validate the refreshed tokens correspond to the authenticated admin user
  TestValidator.equals(
    "refreshed admin id equals original",
    refreshed.id,
    authorized.id,
  );
  TestValidator.equals(
    "refreshed admin email equals original",
    refreshed.email,
    authorized.email,
  );

  // 4. Validate new access and refresh tokens are non-empty and different from original
  TestValidator.predicate(
    "new access token is non-empty",
    refreshed.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token is non-empty",
    refreshed.token.refresh.length > 0,
  );
  TestValidator.notEquals(
    "access token should change",
    refreshed.token.access,
    authorized.token.access,
  );
  TestValidator.notEquals(
    "refresh token should change",
    refreshed.token.refresh,
    authorized.token.refresh,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
