    "created_at is ISO_date-time",
    !isNaN(Date.parse(authorizedSeller.created_at)),
  );
  TestValidator.predicate(
    "updated_at is ISO_date-time",
    !isNaN(Date.parse(authorizedSeller.updated_at)),
  );

