import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdmin";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

export async function test_api_shopping_mall_admins_list_with_filters_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin user registration and authentication
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const authorizedAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email,
        password: "StrongPassw0rd!",
        ip: null,
        href: "https://shopping-mall.example.com/admin/join",
        referrer: "https://shopping-mall.example.com/",
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(authorizedAdmin);

  // 2. Prepare request body for filtered list with pagination and sorting
  const requestBody = {
    page: 1,
    limit: 10,
    search: email.substring(0, Math.min(10, email.length)), // Partial email for search
    sortField: "email",
    sortOrder: "asc",
  } satisfies IShoppingMallAdmin.IRequest;

  // 3. Call the admin list API to get filtered paginated admins
  const page: IPageIShoppingMallAdmin.ISummary =
    await api.functional.shoppingMall.admin.shoppingMallAdmins.index(
      connection,
      {
        body: requestBody,
      },
    );

  // 4. Validate the pagination data structure
  typia.assert(page);
  const pagination: IPage.IPagination = page.pagination;
  TestValidator.predicate(
    "page pagination current page is positive",
    pagination.current > 0,
  );
  TestValidator.predicate(
    "page pagination limit is positive",
    pagination.limit > 0,
  );
  TestValidator.predicate(
    "page pagination records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "page pagination pages is positive",
    pagination.pages > 0,
  );

  // 5. Validate the data list
  const data = page.data;
  TestValidator.predicate(
    "page data not empty and does not exceed limit",
    data.length <= pagination.limit,
  );

  // 6. Each admin entry validation
  for (const admin of data) {
    typia.assert(admin);
    TestValidator.predicate(
      "each admin id is uuid format",
      /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(
        admin.id,
      ),
    );
    TestValidator.predicate(
      "each admin email contains search keyword",
      admin.email.includes(requestBody.search ?? ""),
    );
  }

  // 7. Validate sorting: emails ascending
  for (let i = 1; i < data.length; i++) {
    TestValidator.predicate(
      `email at index ${i} >= email at index ${i - 1}`,
      data[i].email >= data[i - 1].email,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSnapshot";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShoppingMallCategory";

/**
 * Tests shopping mall admin product snapshot retrieval.
 *
 * Business scenario:
 *
 * 1. Admin actor joins and authenticates.
 * 2. Seller actor joins and authenticates.
 * 3. Seller creates a shopping mall product.
 * 4. Admin authenticates (login) to start snapshot retrieval.
 * 5. Admin retrieves the created product's snapshot by snapshot ID.
 *
 * Validations:
 *
 * - Snapshot data matches the product data created originally.
 * - Audit timestamps in snapshot are valid and correspond to creation.
 * - Authorization is handled appropriately.
 *
 * The test ensures end-to-end secure access, data integrity, and proper audit
 * tracking through product snapshots.
 */
export async function test_api_shopping_mall_admin_shopping_mall_product_snapshot_retrieval(
  connection: api.IConnection,
) {
  // 1. Admin actor joins and authenticates
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        ip: null,
        href: "https://www.example.com/admin",
        referrer: "https://www.example.com",
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Seller actor joins and authenticates
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "1234";
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 3. Seller creates a shopping mall product
  const categoryCode: string = RandomGenerator.alphaNumeric(8);
  const productCode = RandomGenerator.alphaNumeric(10);
  const productTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const productDescription = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 8,
    sentenceMax: 15,
    wordMin: 4,
    wordMax: 8,
  });
  const productBrand = RandomGenerator.name(2);

  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.shoppingMallProducts.create(
      connection,
      {
        body: {
          code: productCode,
          title: productTitle,
          description: productDescription,
          brand: productBrand,
          category_code: categoryCode,
        } satisfies IShoppingMallProduct.ICreate,
      },
    );
  typia.assert(product);

  // 4. Admin authenticates (login)
  const adminLoggedIn: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        ip: null,
        href: "https://www.example.com/admin",
        referrer: "https://www.example.com",
      } satisfies IShoppingMallAdmin.ILogin,
    });
  typia.assert(adminLoggedIn);

  // 5. Admin retrieves the product snapshot by ID
  // Note: product.id is product ID, not snapshot ID; we retrieve snapshot using product snapshot ID
  // Since no API to create snapshot separately, simulate snapshot retrieval by using product.id as base
  const snapshot: IShoppingMallProductSnapshot =
    await api.functional.shoppingMall.admin.shoppingMallProducts.snapshots.at(
      connection,
      {
        id: product.id,
      },
    );
  typia.assert(snapshot);

  // Validations
  TestValidator.equals(
    "Snapshot product ID matches original product ID",
    snapshot.shopping_mall_product_id,
    product.id,
  );
  TestValidator.equals(
    "Snapshot code matches product code",
    snapshot.code,
    product.code,
  );
  TestValidator.equals(
    "Snapshot title matches product title",
    snapshot.title,
    product.title,
  );

  if (product.description === null || product.description === undefined) {
    TestValidator.equals(
      "Snapshot description is null as expected",
      snapshot.description,
      null,
    );
  } else {
    TestValidator.equals(
      "Snapshot description matches product description",
      snapshot.description,
      product.description,
    );
  }

  if (product.brand === null || product.brand === undefined) {
    TestValidator.equals(
      "Snapshot brand is null as expected",
      snapshot.brand,
      null,
    );
  } else {
    TestValidator.equals(
      "Snapshot brand matches product brand",
      snapshot.brand,
      product.brand,
    );
  }

  TestValidator.predicate(
    "Snapshot snapshot_at is string and non-empty",
    typeof snapshot.snapshot_at === "string" && snapshot.snapshot_at.length > 0,
  );
  TestValidator.predicate(
    "Snapshot created_at is string and non-empty",
    typeof snapshot.created_at === "string" && snapshot.created_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCart";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

export async function test_api_shopping_mall_customer_shopping_mall_cart_list(
  connection: api.IConnection,
) {
  // 1. Register a new customer to authenticate
  const email = `${RandomGenerator.alphaNumeric(8).toLowerCase()}@test.com`;
  const password = RandomGenerator.alphaNumeric(12);

  const newCustomer = {
    email,
    password,
    href: "https://example.com/signup",
    referrer: "https://example.com/referrer",
  } satisfies IShoppingMallCustomer.ICreate;

  const authorizedCustomer = await api.functional.auth.customer.join(
    connection,
    {
      body: newCustomer,
    },
  );
  typia.assert(authorizedCustomer);

  // 2. Test empty filter - expect initial page response
  const emptyRequest = {} satisfies IShoppingMallCart.IRequest;
  const emptyResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: emptyRequest },
    );
  typia.assert(emptyResult);
  TestValidator.predicate(
    "empty result has pagination and data arrays",
    emptyResult.pagination !== undefined && Array.isArray(emptyResult.data),
  );

  // 3. Filter by created_at_from (30 days ago)
  const createdAtFrom = new Date(
    Date.now() - 30 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const createdFromRequest = {
    created_at_from: createdAtFrom,
  } satisfies IShoppingMallCart.IRequest;
  const createdFromResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: createdFromRequest },
    );
  typia.assert(createdFromResult);

  // 4. Filter by created_at_to (1 day future)
  const createdAtTo = new Date(
    Date.now() + 1 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const createdToRequest = {
    created_at_to: createdAtTo,
  } satisfies IShoppingMallCart.IRequest;
  const createdToResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: createdToRequest },
    );
  typia.assert(createdToResult);

  // 5. Filter by updated_at_from and updated_at_to
  const updatedFromToRequest = {
    updated_at_from: createdAtFrom,
    updated_at_to: createdAtTo,
  } satisfies IShoppingMallCart.IRequest;
  const updatedFromToResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: updatedFromToRequest },
    );
  typia.assert(updatedFromToResult);

  // 6. Filter by deleted_at null
  const deletedAtNullRequest = {
    deleted_at: null,
  } satisfies IShoppingMallCart.IRequest;
  const deletedAtNullResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: deletedAtNullRequest },
    );
  typia.assert(deletedAtNullResult);

  // 7. Pagination test (page 2, limit 10)
  const paginationRequest = {
    page: 2,
    limit: 10,
  } satisfies IShoppingMallCart.IRequest;
  const paginationResult =
    await api.functional.shoppingMall.customer.shoppingMallCarts.index(
      connection,
      { body: paginationRequest },
    );
  typia.assert(paginationResult);
  TestValidator.predicate(
    "pagination has correct current and limit values",
    paginationResult.pagination.current === 2 &&
      paginationResult.pagination.limit === 10,
  );

  // 8. Validate carts data for each result
  const results = [
    emptyResult,
    createdFromResult,
    createdToResult,
    updatedFromToResult,
    deletedAtNullResult,
    paginationResult,
  ];

  for (const result of results) {
    for (const cart of result.data) {
      typia.assert(cart);

      TestValidator.predicate(
        `cart.id is valid UUID: ${cart.id}`,
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
          cart.id,
        ),
      );

      TestValidator.predicate(
        `cart.shopping_mall_customer_id is valid UUID: ${cart.shopping_mall_customer_id}`,
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
          cart.shopping_mall_customer_id,
        ),
      );

      if (
        cart.shopping_mall_customer_session_id !== null &&
        cart.shopping_mall_customer_session_id !== undefined
      ) {
        typia.assert<string & tags.Format<"uuid">>(
          cart.shopping_mall_customer_session_id,
        );
      }

      typia.assert<string & tags.Format<"date-time">>(cart.created_at);
      typia.assert<string & tags.Format<"date-time">>(cart.updated_at);

      if (cart.deleted_at !== null && cart.deleted_at !== undefined) {
        typia.assert<string & tags.Format<"date-time">>(cart.deleted_at);
      }
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";

export async function test_api_shopping_mall_customer_session_detail_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins and authenticates
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "admin1234",
        ip: "127.0.0.1",
        href: "https://example.com/admin/join",
        referrer: "https://example.com/login",
      } satisfies IShoppingMallAdmin.IJoin,
    });

  typia.assert(admin);

  // 2. Create a shopping mall customer
  const customerEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const customerBody = {
    email: customerEmail,
    password: "customerpass",
    href: "https://example.com/signup",
    referrer: "https://example.com/landing",
  } satisfies IShoppingMallCustomer.ICreate;

  const customer: IShoppingMallCustomer =
    await api.functional.shoppingMall.customer.shoppingMallCustomers.create(
      connection,
      {
        body: customerBody,
      },
    );

  typia.assert(customer);

  // 3. Create a shopping mall customer session for the created customer
  const sessionBody = {
    ip: "192.168.1.100",
    href: "https://example.com/customer/session",
    referrer: "https://example.com/home",
    expired_at: null,
    is_active: true,
    device_info: "Test Device",
    user_agent: "Mozilla/5.0 (compatible; TestBot/1.0)",
  } satisfies IShoppingMallCustomerSession.ICreate;

  const session: IShoppingMallCustomerSession =
    await api.functional.shoppingMall.customer.shoppingMallCustomers.shoppingMallCustomerSessions.create(
      connection,
      {
        shoppingMallCustomerId: customer.id,
        body: sessionBody,
      },
    );
  typia.assert(session);

  // 4. Admin retrieves the detailed shopping mall customer session
  const sessionDetail: IShoppingMallCustomerSession =
    await api.functional.shoppingMall.admin.shoppingMallCustomers.shoppingMallCustomerSessions.at(
      connection,
      {
        shoppingMallCustomerId: customer.id,
        shoppingMallCustomerSessionId: session.id,
      },
    );
  typia.assert(sessionDetail);

  // 5. Validate retrieved data
  TestValidator.equals(
    "admin retrieved session id matches created",
    sessionDetail.id,
    session.id,
  );
  TestValidator.equals(
    "admin retrieved session customer id matches created customer",
    sessionDetail.shopping_mall_customer_id,
    customer.id,
  );
  TestValidator.equals(
    "sessionDetail.ip matches",
    sessionDetail.ip,
    sessionBody.ip,
  );
  TestValidator.equals(
    "sessionDetail.href matches",
    sessionDetail.href,
    sessionBody.href,
  );
  TestValidator.equals(
    "sessionDetail.referrer matches",
    sessionDetail.referrer,
    sessionBody.referrer,
  );
  TestValidator.equals(
    "sessionDetail.expired_at matches",
    sessionDetail.expired_at,
    sessionBody.expired_at,
  );
  TestValidator.equals(
    "sessionDetail.is_active matches",
    sessionDetail.is_active,
    sessionBody.is_active,
  );
  TestValidator.equals(
    "sessionDetail.device_info matches",
    sessionDetail.device_info,
    sessionBody.device_info,
  );
  TestValidator.equals(
    "sessionDetail.user_agent matches",
    sessionDetail.user_agent,
    sessionBody.user_agent,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";

/**
 * This test validates the creation of a shopping mall customer session by a
 * newly joined customer.
 *
 * The steps are:
 *
 * 1. Perform a join operation to register a new customer and authenticate.
 * 2. Create a shopping mall customer entity separately.
 * 3. Create a new session for the customer using valid connection properties.
 * 4. Validate that the session creation response has expected values.
 * 5. Verify important fields such as shoppingMallCustomerId, is_active, IP, href,
 *    etc.
 */
export async function test_api_shopping_mall_customer_session_creation_by_customer(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new customer via join
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://example.com/signup",
    referrer: "https://google.com",
  } satisfies IShoppingMallCustomer.ICreate;

  const authorizedCustomer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: joinInput,
    });
  typia.assert(authorizedCustomer);

  // 2. Create a shopping mall customer entity
  const customerCreateInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://example.com/create-customer",
    referrer: "https://example.com",
  } satisfies IShoppingMallCustomer.ICreate;

  const customer: IShoppingMallCustomer =
    await api.functional.shoppingMall.customer.shoppingMallCustomers.create(
      connection,
      {
        body: customerCreateInput,
      },
    );
  typia.assert(customer);

  // 3. Create a shopping mall customer session for the customer
  const sessionCreateInput = {
    ip: "192.168.1.1",
    href: "https://example.com/home",
    referrer: "https://google.com",
    expired_at: null,
    duration_minutes: 60,
    is_active: true,
    device_info: "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
    user_agent:
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36",
  } satisfies IShoppingMallCustomerSession.ICreate;

  const session: IShoppingMallCustomerSession =
    await api.functional.shoppingMall.customer.shoppingMallCustomers.shoppingMallCustomerSessions.create(
      connection,
      {
        shoppingMallCustomerId: customer.id,
        body: sessionCreateInput,
      },
    );
  typia.assert(session);

  // 4. Validate session creation response fields
  TestValidator.equals(
    "Session's customer id matches",
    session.shopping_mall_customer_id,
    customer.id,
  );
  TestValidator.predicate("Session is active", session.is_active);
  TestValidator.equals("Session IP address", session.ip, sessionCreateInput.ip);
  TestValidator.equals(
    "Session href URL",
    session.href,
    sessionCreateInput.href,
  );
  TestValidator.equals(
    "Session referrer URL",
    session.referrer,
    sessionCreateInput.referrer,
  );
  TestValidator.equals(
    "Session device info",
    session.device_info ?? "",
    sessionCreateInput.device_info ?? "",
  );
  TestValidator.equals(
    "Session user agent",
    session.user_agent ?? "",
    sessionCreateInput.user_agent ?? "",
  );
  // Check created_at is ISO string and parsable
  TestValidator.predicate(
    "Session created_at is ISO date",
    typeof session.created_at === "string" &&
      !isNaN(Date.parse(session.created_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

export async function test_api_shopping_mall_admin_shopping_mall_sellers_retrieve_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins to obtain authorization token
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "1234",
        ip: null,
        href: "https://testing.example.com/join",
        referrer: "https://referrer.example.com/",
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Admin creates a shopping mall seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller =
    await api.functional.shoppingMall.admin.shoppingMallSellers.create(
      connection,
      {
        body: {
          email: sellerEmail,
          password: "1234",
        } satisfies IShoppingMallSeller.ICreate,
      },
    );
  typia.assert(seller);

  // 3. Admin retrieves the created shopping mall seller by ID
  const retrievedSeller: IShoppingMallSeller =
    await api.functional.shoppingMall.admin.shoppingMallSellers.at(connection, {
      shoppingMallSellerId: seller.id,
    });
