import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

export async function test_api_wishlist_item_retrieval_by_customer(
  connection: api.IConnection,
) {
  // Authenticate as a new customer via join
  const customerCreateBody = {
    email: RandomGenerator.alphaNumeric(5) + "@test.com",
    password: "1234",
    href: "https://example.com/wishlist",
    referrer: "https://example.com/home",
  } satisfies IShoppingMallCustomer.ICreate;

  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerCreateBody,
    });
  typia.assert(customer);

  // Create a new wishlist for the authenticated customer
  const wishlistCreateBody = {
    name: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
  } satisfies IShoppingMallWishlist.ICreate;

  const wishlist: IShoppingMallWishlist =
    await api.functional.shoppingMall.customer.shoppingMallWishlists.create(
      connection,
      {
        body: wishlistCreateBody,
      },
    );
  typia.assert(wishlist);

  // Create a new wishlist item inside the wishlist
  // Since the product variant id is required but not provided by user inputs,
  // we use typia.random to generate a random uuid formatted string to simulate a valid product variant id
  const wishlistItemCreateBody = {
    shoppingMallProductVariantId: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallWishlistItem.ICreate;

  const wishlistItem: IShoppingMallWishlistItem =
    await api.functional.shoppingMall.customer.shoppingMallWishlists.shoppingMallWishlistItems.create(
      connection,
      {
        shoppingMallWishlistId: wishlist.id,
        body: wishlistItemCreateBody,
      },
    );
  typia.assert(wishlistItem);

  // Retrieve the wishlist item details by wishlist ID and item ID
  const retrievedItem: IShoppingMallWishlistItem =
    await api.functional.shoppingMall.customer.shoppingMallWishlists.shoppingMallWishlistItems.at(
      connection,
      {
        shoppingMallWishlistId: wishlist.id,
        shoppingMallWishlistItemId: wishlistItem.id,
      },
    );
  typia.assert(retrievedItem);

  // Validate that retrieved item matches created item
  TestValidator.equals(
    "Retrieved wishlist item ID should match created item ID",
    retrievedItem.id,
    wishlistItem.id,
  );

  TestValidator.equals(
    "Retrieved wishlist item wishlist ID should match wishlist ID",
    retrievedItem.shopping_mall_wishlist_id,
    wishlist.id,
  );

  TestValidator.equals(
    "Retrieved wishlist item product variant ID should match created item product variant ID",
    retrievedItem.shopping_mall_product_variant_id,
    wishlistItem.shopping_mall_product_variant_id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

/**
 * Test verifying that admin users can delete a shopping mall product by
 * productCode.
 *
 * This test creates an admin user and authenticates, then deletes a product. It
 * also tests that deletion without authentication is not allowed.
 *
 * Steps:
 *
 * 1. Admin user joins and obtains authorization token.
 * 2. Authenticated admin deletes a product using productCode.
 * 3. Verify deletion succeeded without error.
 * 4. Attempt deletion with unauthenticated connection, expect error.
 */
export async function test_api_shopping_mall_product_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin user joins and authenticates
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPass123!";
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        ip: null,
        href: "https://test.example.com/join",
        referrer: "https://test.example.com/",
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // Clone connection for authenticated requests with token set
  const authConnection: api.IConnection = { ...connection };
  authConnection.headers = { Authorization: admin.token.access };

  // 2. Generate a realistic productCode
  // As productCode is a string, provide a random alphanumeric string with 12 chars
  const productCode = RandomGenerator.alphaNumeric(12);

  // 3. Admin deletes the product by productCode
  await api.functional.shoppingMall.admin.shoppingMallProducts.erase(
    authConnection,
    {
      productCode,
    },
  );

  // 4. Attempt deletion without authentication, expect error
  const unauthConnection: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "Unauthorized deletion attempt should fail",
    async () => {
      await api.functional.shoppingMall.admin.shoppingMallProducts.erase(
        unauthConnection,
        {
          productCode,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductVariant";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShoppingMallCategory";

export async function test_api_shopping_mall_product_variant_search_by_customer(
  connection: api.IConnection,
) {
  // 1. Create a new customer account via auth.customer.join
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "P@ssw0rd1234";
  const customerAuthorized: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        href: "https://example.com/signup",
        referrer: "https://example.com/home",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customerAuthorized);

  // 2. Create a new seller account via auth.seller.join and login
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "P@ssw0rd1234";
  const sellerAuthorized: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(sellerAuthorized);

  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      ip: null,
      href: "https://example.com/seller/login",
      referrer: "https://example.com/seller/home",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates a product
  // We use a realistic category_code string
  const categoryCode = `cat-${RandomGenerator.alphaNumeric(5)}`;
  const productCode = `prd-${RandomGenerator.alphaNumeric(8)}`;
  const productTitle = `${RandomGenerator.name(3)} Product`;
  const productDescription = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 5,
    sentenceMax: 10,
    wordMin: 4,
    wordMax: 8,
  });
  const productBrand = RandomGenerator.name(1);

  const productCreateBody = {
    code: productCode,
    title: productTitle,
    description: productDescription,
    brand: productBrand,
    category_code: categoryCode,
  } satisfies IShoppingMallProduct.ICreate;

  const createdProduct: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.shoppingMallProducts.create(
      connection,
      {
        body: productCreateBody,
      },
    );
  typia.assert(createdProduct);

  // 4. Customer login to authenticate for variant search
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      ip: null,
      href: "https://example.com/login",
      referrer: "https://example.com/home",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 5. Customer searches product variants by patch /shoppingMall/customer/shoppingMallProducts/{productCode}/shoppingMallProductVariants
  const pageNumber = 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>;
  const limitCount = 10 satisfies number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<100>;

  const variantSearchRequest = {
    color: null,
    size: null,
    option: null,
    min_price: 0,
    max_price: 1000000,
    status: null,
    page: pageNumber,
    limit: limitCount,
    sort_by: "price",
    order: "asc",
  } satisfies IShoppingMallProductVariant.IRequest;

  const variantsPage: IPageIShoppingMallProductVariant.ISummary =
    await api.functional.shoppingMall.customer.shoppingMallProducts.shoppingMallProductVariants.index(
      connection,
      {
        productCode: createdProduct.code,
        body: variantSearchRequest,
      },
    );
  typia.assert(variantsPage);

  // 6. Validate pagination properties
  TestValidator.predicate(
    "pagination current page equals request page",
    variantsPage.pagination.current === pageNumber,
  );
  TestValidator.predicate(
    "pagination limit equals request limit",
    variantsPage.pagination.limit === limitCount,
  );
  TestValidator.predicate(
    "pagination records non-negative",
    variantsPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages non-negative",
    variantsPage.pagination.pages >= 0,
  );

  // 7. Validate that each variant returned has valid id, sku_code, and price
  for (const variant of variantsPage.data) {
    TestValidator.predicate(
      "variant id is uuid format",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
        variant.id,
      ),
    );
    TestValidator.predicate(
      "variant sku_code non-empty string",
      typeof variant.sku_code === "string" && variant.sku_code.length > 0,
    );
    TestValidator.predicate(
      "variant price is non-negative number",
      typeof variant.price === "number" && variant.price >= 0,
    );
  }
}

