import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCouponUsage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCouponUsage";
import { IPageIShoppingMallCouponUsage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCouponUsage";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminCouponUsages(props: {
  admin: AdminPayload;
  body: IShoppingMallCouponUsage.IRequest;
}): Promise<IPageIShoppingMallCouponUsage.ISummary> {
  const {
    coupon_id,
    customer_id,
    order_id,
    used_at_from,
    used_at_to,
    page,
    limit,
    sort_by,
    order_direction,
  } = props.body;

  const whereCondition = {
    ...(coupon_id !== undefined && { shopping_mall_coupon_id: coupon_id }),
    ...(customer_id !== undefined && {
      shopping_mall_customer_id: customer_id,
    }),
    order_id:
      order_id === undefined ? undefined : order_id === null ? null : order_id,
    ...(used_at_from !== undefined || used_at_to !== undefined
      ? {
          used_at: {
            ...(used_at_from !== undefined && used_at_from !== null
              ? { gte: used_at_from }
              : {}),
            ...(used_at_to !== undefined && used_at_to !== null
              ? { lte: used_at_to }
              : {}),
          },
        }
      : {}),
  };

  const pageNumber = page > 0 ? page : 1;
  const pageSize = limit > 0 ? limit : 20;
  const skip = (pageNumber - 1) * pageSize;

  const orderField = sort_by ?? "used_at";
  const orderDir = order_direction ?? "desc";

  const [records, totalCount] = await Promise.all([
    MyGlobal.prisma.shopping_mall_coupon_usages.findMany({
      where: whereCondition,
      skip,
      take: pageSize,
      orderBy: { [orderField]: orderDir },
    }),
    MyGlobal.prisma.shopping_mall_coupon_usages.count({
      where: whereCondition,
    }),
  ]);

  const data = records.map((record) => ({
    id: record.id,
    shopping_mall_coupon_id: record.shopping_mall_coupon_id,
    shopping_mall_customer_id: record.shopping_mall_customer_id,
    used_at: toISOStringSafe(record.used_at),
    order_id: record.order_id === null ? null : (record.order_id ?? undefined),
  }));

  return {
    data,
    pagination: {
      current: pageNumber satisfies number as number,
      limit: pageSize satisfies number as number,
      records: totalCount,
      pages: Math.ceil(totalCount / pageSize),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import { IPageIShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPayment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminPayments(props: {
  admin: AdminPayload;
  body: IShoppingMallPayment.IRequest;
}): Promise<IPageIShoppingMallPayment.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const where = {
    deleted_at: null,
    ...(props.body.payment_method
      ? { payment_method: props.body.payment_method }
      : {}),
    ...(props.body.payment_status
      ? { payment_status: props.body.payment_status }
      : {}),
    ...(props.body.payment_amount_min !== undefined ||
    props.body.payment_amount_max !== undefined
      ? {
          payment_amount: {
            ...(props.body.payment_amount_min !== undefined
              ? { gte: props.body.payment_amount_min }
              : {}),
            ...(props.body.payment_amount_max !== undefined
              ? { lte: props.body.payment_amount_max }
              : {}),
          },
        }
      : {}),
    ...(props.body.payment_date_from || props.body.payment_date_to
      ? {
          payment_date: {
            ...(props.body.payment_date_from
              ? { gte: props.body.payment_date_from }
              : {}),
            ...(props.body.payment_date_to
              ? { lte: props.body.payment_date_to }
              : {}),
          },
        }
      : {}),
  };

  const [payments, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_payments.findMany({
      where,
      skip,
      take: limit,
      orderBy: { payment_date: "desc" },
    }),
    MyGlobal.prisma.shopping_mall_payments.count({ where }),
  ]);

  const data = payments.map((payment) => {
    return {
      id: payment.id,
      order_id: payment.shopping_mall_order_id,
      status: payment.payment_status,
      amount: payment.payment_amount,
      payment_method: payment.payment_method,
      paid_at: payment.payment_date
        ? toISOStringSafe(payment.payment_date)
        : undefined,
    };
  });

  return {
    data,
    pagination: {
      current: page satisfies number as number,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
