  ]);

  return {
    pagination: {
      current: page satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      limit: limit satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      records: totalCount,
      pages: Math.ceil(totalCount / limit),
    },
    data: records.map((rec) => ({
      id: rec.id,
      shopping_mall_product_variant_id: rec.shopping_mall_product_variant_id,
