import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerShoppingMallCartsShoppingMallCartIdShoppingMallCartItems(props: {
  customer: CustomerPayload;
  shoppingMallCartId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.ICreate;
}): Promise<IShoppingMallCartItem> {
  const cart = await MyGlobal.prisma.shopping_mall_carts.findUnique({
    where: { id: props.shoppingMallCartId },
    select: { id: true, shopping_mall_customer_id: true, deleted_at: true },
  });

  if (
    cart === null ||
    cart.deleted_at !== null ||
    cart.shopping_mall_customer_id !== props.customer.id
  ) {
    throw new HttpException("Shopping cart not found or access denied", 404);
  }

  const productVariant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUnique({
      where: { id: props.body.shoppingMallProductVariantId },
      select: { id: true, deleted_at: true },
    });

  if (productVariant === null || productVariant.deleted_at !== null) {
    throw new HttpException("Product variant not found", 404);
  }

  const now = toISOStringSafe(new Date()) satisfies string &
    tags.Format<"date-time"> as string & tags.Format<"date-time">;

  const created = await MyGlobal.prisma.shopping_mall_cart_items.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_cart_id: props.shoppingMallCartId,
      shopping_mall_product_variant_id: props.body.shoppingMallProductVariantId,
      quantity: props.body.quantity,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    shopping_mall_cart_id: created.shopping_mall_cart_id,
    shopping_mall_product_variant_id: created.shopping_mall_product_variant_id,
    quantity: created.quantity,
    created_at: toISOStringSafe(created.created_at) satisfies string &
      tags.Format<"date-time"> as string & tags.Format<"date-time">,
    updated_at: toISOStringSafe(created.updated_at) satisfies string &
      tags.Format<"date-time"> as string & tags.Format<"date-time">,
    deleted_at:
      created.deleted_at !== null
        ? (toISOStringSafe(created.deleted_at) satisfies string &
            tags.Format<"date-time"> as string & tags.Format<"date-time">)
        : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShoppingMallCategory";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerShoppingMallCategories(props: {
  customer: CustomerPayload;
  body: IShoppingMallShoppingMallCategory.ICreate;
}): Promise<IShoppingMallShoppingMallCategory> {
  try {
    const now = toISOStringSafe(new Date());
    const created = await MyGlobal.prisma.shopping_mall_categories.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        name: props.body.name,
        description:
          props.body.description === undefined
            ? undefined
            : (props.body.description ?? null),
        status: props.body.status,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });

    return {
      id: created.id,
      name: created.name,
      description: created.description ?? null,
      status: created.status,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at:
        created.deleted_at === null
          ? null
          : toISOStringSafe(created.deleted_at),
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002" &&
      Array.isArray(error.meta?.target) &&
      error.meta.target.includes("name")
    ) {
      throw new HttpException(`Category name must be unique.`, 409);
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCategoryHierarchy } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategoryHierarchy";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerShoppingMallCategoriesCategoryNameShoppingMallCategoryHierarchies(props: {
  customer: CustomerPayload;
  categoryName: string;
  body: IShoppingMallCategoryHierarchy.ICreate;
}): Promise<IShoppingMallCategoryHierarchy> {
  const parentCategory =
    await MyGlobal.prisma.shopping_mall_categories.findUnique({
      where: {
        name: props.categoryName,
      },
    });
  if (!parentCategory) {
    throw new HttpException(
      `Parent category '${props.categoryName}' not found`,
      404,
    );
  }

  const childCategory =
    await MyGlobal.prisma.shopping_mall_categories.findUnique({
      where: {
        id: props.body.child_category_id,
      },
    });
  if (!childCategory) {
    throw new HttpException(
      `Child category with id '${props.body.child_category_id}' not found`,
      404,
    );
  }

  const existingLink =
    await MyGlobal.prisma.shopping_mall_category_hierarchies.findUnique({
      where: {
        parent_category_id_child_category_id: {
          parent_category_id: parentCategory.id,
          child_category_id: childCategory.id,
        },
      },
    });
  if (existingLink) {
    throw new HttpException("Hierarchy link already exists", 400);
  }

  const now = toISOStringSafe(new Date());

  const created =
    await MyGlobal.prisma.shopping_mall_category_hierarchies.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        parent_category_id: parentCategory.id,
        child_category_id: childCategory.id,
        created_at: now,
        updated_at: now,
      },
    });

  return {
    id: created.id,
    parent_category_name: parentCategory.name,
    child_category_name: childCategory.name,
    display_order: undefined,
    is_active: true,
    created_at: toISOStringSafe(created.created_at),
    updated_at: created.updated_at
      ? toISOStringSafe(created.updated_at)
      : undefined,
    notes: undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerShoppingMallCustomers(props: {
  customer: CustomerPayload;
  body: IShoppingMallCustomer.ICreate;
}): Promise<IShoppingMallCustomer> {
  try {
    const hashedPassword = await PasswordUtil.hash(props.body.password);
    const now = toISOStringSafe(new Date());

    const created = await MyGlobal.prisma.shopping_mall_customers.create({
      data: {
        id: v4(),
        email: props.body.email,
        password_hash: hashedPassword,
        created_at: now,
        updated_at: now,
      },
    });

    return {
      id: created.id,
      email: created.email,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
    };
  } catch (error: unknown) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      if (
        Array.isArray(error.meta?.target) &&
        error.meta.target.includes("email")
      ) {
        throw new HttpException("Email already exists", 400);
      }
    }
    throw error;
  }
}

