    MyGlobal.prisma.shopping_mall_points.count({ where: whereCondition }),
  ]);

  return {
    data: results.map((item) => ({
      id: item.id,
      balance: item.balance,
      shopping_mall_customer_id: item.shopping_mall_customer_id,
    })),
    pagination: {
      current: pageInt,
